"""${{ values.name }} — generated by the batch blueprint v3.0.0."""
import os

from platform_sdk import Context, Gateway

ALIAS = os.environ.get("SERVICE_ALIAS", "${{ values.alias }}")
gateway = Gateway(ctx=Context(tenant="${{ values.tenant }}", feature="batch"))


def run(records: list[dict]) -> list[dict]:
    out = []
    for r in records:
        out.append({**r, "label": gateway.chat([{"role": "user", "content": r["text"]}], alias=ALIAS, max_tokens=16).text})
    return out


def eval_answer(question: str):
    return run([{"text": question}])[0]["label"], []
